struct BuddyState { int path; int moving; bool active; BuddyState& operator=(const BuddyState& o) { path = o.path; moving = o.moving; active = o.active; return *this; } };
struct BuddyInfo { BuddyInfo() : soldier(0), progress(0) { BuddyState unused = state; state.moving = 0; state.active = false; state.path = 0; } BuddyInfo(const BuddyInfo& o) : soldier(o.soldier), progress(o.progress) { state.moving = o.state.moving; state.active = o.state.active; state.path = o.state.path; } void* soldier; int progress; BuddyState state; };
